PROFILES={"focus_C":{"fan_C":.35,"side_AB":.35,"GS_HIST_DOUBLE_TRIANGLE":.2,"GS_HIST_MEDIAL_POLYROLE":.1},"focus_A":{"fan_A":.35,"side_BC":.35,"GS_HIST_DOUBLE_TRIANGLE":.2,"GS_HIST_MEDIAL_POLYROLE":.1}}
BRIDGE_MIN=.6
GS_MIN=.75
AXIS_MIN=2/3
FAN_LEVELS=["No new interior contact or partition of either incident carrier.","At least one incident carrier gains an interior contact, without an apex split or a connector across both incident carriers.","Interior points of both incident carriers are joined to enclose a smaller apex region, without splitting the angle at its vertex.","The new connector starts at this vertex and ends inside the opposite side, partitioning the angular fan."]
SIDE_LEVELS=["The new connector makes no contact with this carrier.","The connector touches an original endpoint but makes no new interior contact with this carrier.","The connector ends inside this carrier, with its other endpoint away from the opposite original vertex.","The connector joins an interior point of this carrier to the opposite original vertex."]
PAIR_LEVELS=["No new shared boundary and no two induced regions.","Only one region or an incidental contact, without two adjacent closed regions.","Two closed adjacent regions share the new carrier, but they are not both triangles.","Two adjacent triangles share the same new material carrier as a side."]
