DIMENSIONS=[("fan_"+v,{"kind":"angular_fan","vertex":v,"members":[v+x for x in "ABC" if x!=v]},FAN_LEVELS) for v in "ABC"]+[("side_"+s,{"kind":"segment_carrier","endpoints":list(s)},SIDE_LEVELS) for s in ("AB","BC","AC")]+[("GS_HIST_DOUBLE_TRIANGLE",{"kind":"existing_generic_template","roles":"two adjacent triangular regions using the same new material carrier"},PAIR_LEVELS),("GS_HIST_MEDIAL_POLYROLE",{"kind":"existing_generic_template","roles":"one material object with distinct boundary and host-partition participations"},POLY_LEVELS)]
LIMITS=["Native Score values are Jev outputs; normalization and weighted composites are deterministic code with fixed predeclared profiles.","Existing MS and GS are axes of compatibility, not an exclusive list of correct answers. Weights encode a preference, not universal bridge quality.","Geometry, region extraction and two new schema proposals are generated by code; Jev scores/ranks supplied hypotheses rather than inventing free-form Generic Spaces.","All ten historical Generic Spaces are evaluated, plus two generated hypotheses. The repository has five proposition records, not a full Euclid library.","Structural/metric binding checks are independent gates. A model score does not certify proof or allow a composite to compensate for a missing premise.","The 8-versus-220 comparison has four timing pairs and 32 overlapping Score observations; it does not demonstrate 200 or 2000 distinct theorem schemas.","Per-request default context is 64k and per-question context 32k. No long-context header is enabled. Body limit is 32 MiB; no separate question-count cap is documented.","Claims about 200/2000 schemas are sizing scenarios, not live measurements or invented corpus contents."]

def area(names,p):
    return abs(sum(p[names[i]][0]*p[names[(i+1)%len(names)]][1]-p[names[(i+1)%len(names)]][0]*p[names[i]][1] for i in range(len(names)))/2)

def proposal(shape,method):
    points=geometry.points(shape);names=list("ABC")
    segment=[] if method=="no_op" else list(geometry.TOPOLOGY[method]["endpoints"])
    for n in segment:
        if n not in names:names.append(n)
    p={n:points[n] for n in names};faces=[]
    if segment:
        ring=[]
        for a,b in (("A","B"),("B","C"),("C","A")):
            ring.append(a);inside=[n for n in segment if n not in "ABC" and geometry.interior_between(p[a],p[n],p[b])]
            inside.sort(key=lambda n:math.dist(p[a],p[n]));ring.extend(inside)
        i,j=ring.index(segment[0]),ring.index(segment[1])
        def path(start,end):
            out=[ring[start]]
            while start!=end:start=(start+1)%len(ring);out.append(ring[start])
            return out
        faces=[path(i,j),path(j,i)]
        assert all(len(f)>=3 and area(f,p)>0 for f in faces)
        assert abs(sum(area(f,p) for f in faces)-area(list("ABC"),p))<1e-6
    return {"points":p,"new_segment":segment,"regions":faces,"certified_metric_equalities":[]}

def bridge_oracle(shape,method):
    graph=proposal(shape,method);p=graph["points"];ends=graph["new_segment"];faces=graph["regions"];scores={}
    for v in "ABC":
        others=[n for n in "ABC" if n!=v]
        if not ends:value=0
        elif v in ends and geometry.interior_between(p[others[0]],p[ends[1] if ends[0]==v else ends[0]],p[others[1]]):value=3
        elif any(geometry.interior_between(p[v],p[ends[0]],p[a]) and geometry.interior_between(p[v],p[ends[1]],p[b]) for a,b in (others,list(reversed(others)))):value=2
        elif any(geometry.interior_between(p[v],p[n],p[a]) for n in ends for a in others):value=1
        else:value=0
        scores["fan_"+v]=value
    for a,b in (("A","B"),("B","C"),("A","C")):
        opp=next(n for n in "ABC" if n not in (a,b))
        contact=any(geometry.interior_between(p[a],p[n],p[b]) for n in ends)
        value=3 if contact and opp in ends else 2 if contact else 1 if any(n in (a,b) for n in ends) else 0
        scores["side_"+a+b]=value
    scores["GS_HIST_DOUBLE_TRIANGLE"]=3 if faces and all(len(f)==3 for f in faces) else 2 if faces else 0
    scores["GS_HIST_MEDIAL_POLYROLE"]=3 if faces else 0
    return scores

def schemas():
    records=[]
    for e in MEMORY["entries"]:
        record={"roles":[{"role":r["role"],"relation":r["relation"]} for r in e["abstract_roles"]]}
        if e["id"]=="GS_HIST_DOUBLE_TRIANGLE":record["required_region_types"]=["triangle","triangle"]
        if e["kind"]!="workspace_abstraction":record["premise_policy"]="Catalogued premises and conclusions require certified bindings; do not infer them from appearance."
        records.append((e["id"],"memory",record))
    records.extend([("NEW_SHARED_INTERFACE","grammar_proposal",{"roles":[{"role":"region_pair","relation":"two adjacent closed polygonal regions"},{"role":"interface","relation":"the same newly constructed segment is a boundary of both regions"}]}),("NEW_CONGRUENT_PAIR","grammar_proposal",{"roles":[{"role":"region_pair","relation":"two adjacent closed polygonal regions"},{"role":"pair_relation","relation":"congruence of the two regions, requiring certified metric support"}]})])
    return records

def binding_check(shape,method,schema):
    g=proposal(shape,method);faces=g["regions"]
    if not faces:return {"instantiated":False,"reason":"no_new_region_pair"}
    if schema=="GS_HIST_DOUBLE_TRIANGLE":ok=all(len(f)==3 for f in faces);reason="region_types"
    elif schema in ("GS_HIST_MEDIAL_POLYROLE","NEW_SHARED_INTERFACE"):ok=len(set(faces[0])&set(faces[1]))==2;reason="shared_interface_and_partition"
    elif schema=="NEW_CONGRUENT_PAIR":ok=False;reason="no_certified_congruence_and_unequal_region_areas"
    else:ok=False;reason="required_metric_circle_or_distinct_genealogy_premises_not_bound"
    if schema=="NEW_CONGRUENT_PAIR":assert abs(area(faces[0],g["points"])-area(faces[1],g["points"]))>1e-6
    return {"instantiated":ok,"reason":reason}

def build_payload(out,shape,repeat):
    seed=SEED+100*list(geometry.SHAPES).index(shape)+repeat;rng=random.Random(seed)
    methods=list(METHODS);rng.shuffle(methods);mapping={"C"+str(v):m for v,m in zip(rng.sample(range(100,999),5),methods)}
    before=geometry.render(out/"images"/shape/"initial.png",shape)
    asset_files={"initial":before};candidates=[];graphs={}
    for code,method in mapping.items():
        key="initial" if method=="no_op" else "view_"+code
        if key!="initial":asset_files[key]=geometry.render(out/"images"/shape/(method+".png"),shape,method)
        graphs[code]=proposal(shape,method)
        candidates.append({"id":code,"image":key,"hypothetical_geometry":graphs[code]})
    assets={k:{"type":"image","format":"png","data_base64":base64.b64encode(p.read_bytes()).decode("ascii")} for k,p in asset_files.items()}
    state={"initial_image":"initial","existing_mental_spaces":[{"id":k,"description":d} for k,d,_ in DIMENSIONS if not k.startswith("GS_")],"existing_generic_spaces":[{"id":"G1","roles":DIMENSIONS[6][1]},{"id":"G2","roles":DIMENSIONS[7][1]}],"hypothetical_candidates":candidates,"epistemic_status":"Prospective construction proposals with code-extracted incidences. No metric equality, congruence or theorem is certified. Compare each proposal with the initial workspace."}
    questions={};meta={};serial=0
    def add(instructions,criteria,info):
        nonlocal serial
        serial+=1;q="Q"+str(serial).zfill(4);questions[q]={"type":"score","instructions":instructions,"criteria":criteria};meta[q]=info
    library=schemas();rng.shuffle(library)
    state["schema_hypotheses"]={"H"+str(i+1):record for i,(_,_,record) in enumerate(library)}
    for code,method in mapping.items():
        for axis,description,levels in DIMENSIONS:
            add({"candidate":code,"reference_space":description,"question":"How does this hypothetical new connector engage or instantiate this existing space? Judge only this dimension using the supplied levels; the unchanged initial figure is not a new bridge."},levels,{"stage":"bridge","candidate":code,"axis":axis})
        for i,(schema,origin,record) in enumerate(library):
            for region in (0,1):
                boundary=graphs[code]["regions"][region] if graphs[code]["regions"] else []
                add({"candidate":code,"schema_ref":"H"+str(i+1),"region_boundary_nodes":boundary,"question":"Using schema_ref in state.schema_hypotheses, how completely does this proposed region supply its local object and relation roles in the schema? Empty region supplies no roles. Do not import an unbound metric premise."},LOCAL_LEVELS,{"stage":"generic","candidate":code,"schema":schema,"schema_origin":origin,"axis":"region_"+str(region+1)})
            add({"candidate":code,"schema_ref":"H"+str(i+1),"question":"Using schema_ref in state.schema_hypotheses, how completely is this schema's cross-space relation instantiated by the proposed pair of regions and the supplied certified facts? A theorem premise is not established by a plausible drawing."},ALIGN_LEVELS,{"stage":"generic","candidate":code,"schema":schema,"schema_origin":origin,"axis":"alignment"})
    assert len(questions)==220
    payload={"model":"jev-1.14.0","assets":assets,"state":state,"questions":questions}
    audit=[{"asset":k,"file":p.relative_to(out).as_posix(),"sha256":hashlib.sha256(p.read_bytes()).hexdigest()} for k,p in asset_files.items()]
    probe=[q for q,m in meta.items() if m["stage"]=="bridge" and mapping[m["candidate"]]=="from_C"]
    return payload,mapping,meta,audit,probe

def sanitize(raw,questions):
    def num(value):return value if isinstance(value,(int,float)) and not isinstance(value,bool) and math.isfinite(value) else None
    clean={}
    for key,q in questions.items():
        a=raw.get("answers",{}).get(key,{});score=num(a.get("score"));top=len(q["criteria"])-1
        if score is None or not 0<=score<=top:raise ValueError("invalid_native_score")
        probabilities=a.get("probabilities",{})
        if not isinstance(probabilities,dict) or set(probabilities)!={str(i) for i in range(top+1)}:raise ValueError("invalid_level_probabilities")
        probs={k:num(v) for k,v in probabilities.items()}
        if any(v is None or not 0<=v<=1 for v in probs.values()):raise ValueError("invalid_probability")
        clean[key]={"type":"score","score":score,"normalized_score":score/top,"confidence":num(a.get("confidence")),"probabilities":probs,"reliability":num(a.get("reliability")),"score_probability_delta":score-sum(int(k)*v for k,v in probs.items())}
    usage=raw.get("usage",{})
    return {"answers":clean,"usage":{k:num(v) for k,v in usage.items() if k in ("input_tokens","output_tokens","total_tokens")},"reliability":num(raw.get("reliability"))}

def transport(payload):
    if os.getenv("GITHUB_ACTIONS")!="true" or not os.getenv("TYPESAFE_API_KEY"):raise RuntimeError("actions_secret_required")
    import requests
    start=time.perf_counter()
    try:
        res=requests.post("https://api.typesafe.ai/v1/systemone",headers={"Authorization":"Bearer "+os.environ["TYPESAFE_API_KEY"],"TypeSafe-Danger-Zone-Images":"true"},json=payload,timeout=180)
        if res.status_code!=200:
            body=res.text.lower()
            result={"failure":"HTTP_"+str(res.status_code),"validation_flags":{k:k in body for k in ("context","token","question","criteria","limit","length","image","validation","65536","32768","200","220","128")}}
        else:result={"response":sanitize(res.json(),payload["questions"])}
    except Exception:result={"failure":"transport_or_score_schema_failure"}
    result["elapsed_seconds"]=time.perf_counter()-start
    return result

def weighted(values,weights):
    assert abs(sum(weights.values())-1)<1e-9 and all(v>=0 for v in weights.values())
    return sum(values[k]*w for k,w in weights.items())

def analyze(records):
    groups=[];generic=[];timing=[]
    bycase={}
    for r in records:bycase.setdefault((r["shape"],r["repeat"]),{})[r["kind"]]=r
    for cell,pair in bycase.items():
        full=pair.get("full");probe=pair.get("probe")
        if not full or not full.get("response"):continue
        axes={c:{} for c in full["candidate_mapping"]};hyp={c:{} for c in axes}
        for q,answer in full["response"]["answers"].items():
            m=full["question_metadata"][q]
            if m["stage"]=="bridge":axes[m["candidate"]][m["axis"]]=answer["normalized_score"]
            else:hyp[m["candidate"]].setdefault(m["schema"],{})[m["axis"]]=answer["normalized_score"]
        for name,weights in PROFILES.items():
            ranked=sorted([{"candidate":c,"method":m,"axis_scores":axes[c],"composite":weighted(axes[c],weights),"geometry_admissible":bool(proposal(full["shape"],m)["regions"]),"reference_axis_levels":bridge_oracle(full["shape"],m)} for c,m in full["candidate_mapping"].items()],key=lambda v:-v["composite"])
            valid=[v for v in ranked if v["geometry_admissible"]];best=valid[0]["composite"];ties=[v["method"] for v in valid if abs(v["composite"]-best)<1e-9]
            expected="from_C" if name=="focus_C" else "from_A"
            groups.append({"shape":full["shape"],"repeat":full["repeat"],"profile":name,"weights":weights,"ranking":ranked,"top_methods":ties,"reference_method":expected,"unique_reference_top":ties==[expected],"selected_method":ties[0] if len(ties)==1 and best>=BRIDGE_MIN else None,"selection_threshold":BRIDGE_MIN})
        for c,values in hyp.items():
            method=full["candidate_mapping"][c]
            for schema,scores in values.items():
                composite=sum(scores.values())/3
                raw=composite>=GS_MIN and min(scores.values())>=AXIS_MIN
                check=binding_check(full["shape"],method,schema)
                generic.append({"shape":full["shape"],"repeat":full["repeat"],"candidate":c,"method":method,"schema":schema,"origin":"grammar_proposal" if schema.startswith("NEW_") else "memory","axis_scores":scores,"composite":composite,"model_supported":raw,"independent_binding_check":check,"accepted_binding":raw and check["instantiated"]})
        if probe and probe.get("response"):
            delta=[abs(v["normalized_score"]-full["response"]["answers"][q]["normalized_score"]) for q,v in probe["response"]["answers"].items()]
            timing.append({"shape":full["shape"],"repeat":full["repeat"],"probe_questions":8,"full_questions":220,"probe_seconds":probe["elapsed_seconds"],"full_seconds":full["elapsed_seconds"],"probe_usage":probe["response"]["usage"],"full_usage":full["response"]["usage"],"overlap_n":len(delta),"mean_absolute_normalized_score_change":sum(delta)/len(delta),"max_absolute_normalized_score_change":max(delta)})
    counts={"api_calls_attempted":sum("response" in r or "failure" in r for r in records),"api_failures":sum("failure" in r for r in records),"native_score_answers":sum(len(r.get("response",{}).get("answers",{})) for r in records),"ranking_groups":len(groups),"unique_reference_top":sum(g["unique_reference_top"] for g in groups),"selected_reference":sum(g["selected_method"]==g["reference_method"] for g in groups),"model_supported_gs_bindings":sum(g["model_supported"] for g in generic),"unsupported_bindings_above_model_threshold":sum(g["model_supported"] and not g["independent_binding_check"]["instantiated"] for g in generic),"accepted_bindings":sum(g["accepted_binding"] for g in generic),"accepted_generated_schema_bindings":sum(g["accepted_binding"] and g["origin"]=="grammar_proposal" for g in generic)}
    return {"counts":counts,"bridge_rankings":groups,"generic_space_bindings":generic,"batch_comparisons":timing}

def viewer(out,report):
    e=html.escape;analysis=report["analysis"];rows=[]
    for g in analysis["bridge_rankings"]:
        rows.append(f"<tr><td>{g['shape']}/{g['repeat']}</td><td>{g['profile']}</td><td>{e(str(g['top_methods']))}</td><td>{e(str(g['selected_method']))}</td><td>{g['reference_method']}</td></tr>")
    body='<!doctype html><html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Native Jev Score Fan-out</title><style>body{font:16px system-ui;max-width:1200px;margin:2em auto;padding:1em;color:#26313d}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccd;padding:.5em}pre{white-space:pre-wrap;overflow-wrap:anywhere}img{width:210px;border:1px solid #ccd}details{margin:1em 0}</style><h1>Native Score bridge ranking and Generic Space search</h1><p>Status: '+e(report["status"])+'. Native per-dimension scores; composites and gates are code. All ten stored schemas plus two code-generated hypotheses are evaluated speculatively for every proposal.</p><pre>'+e(json.dumps(analysis["counts"],indent=2))+'</pre><table><tr><th>Scene</th><th>Priority profile</th><th>Top methods</th><th>Selected</th><th>Independent reference</th></tr>'+"".join(rows)+'</table><details><summary>Profiles, dimension scores and full bridge rankings</summary><pre>'+e(json.dumps(analysis["bridge_rankings"],indent=2))+'</pre></details><details><summary>8 versus 220 native questions</summary><pre>'+e(json.dumps(analysis["batch_comparisons"],indent=2))+'</pre></details><details><summary>Generic Space binding scores and independent checks</summary><pre>'+e(json.dumps(analysis["generic_space_bindings"],indent=2))+'</pre></details>'
    for shape in geometry.SHAPES:
        body+=f"<h2>{shape}</h2>"+"".join(f'<figure style="display:inline-block"><img src="images/{shape}/{m if m!="no_op" else "initial"}.png"><figcaption>{m}</figcaption></figure>' for m in METHODS)
    body+='<details><summary>Raw sanitized Score responses and reconstructable input audit</summary><pre>'+e(json.dumps(report["calls"],indent=2))+'</pre></details></html>'
    (out/"viewer.html").write_text(body,encoding="utf-8")

def save(out,report):
    report["analysis"]=analyze(report["calls"]);tmp=out/"results.tmp";tmp.write_text(json.dumps(report,indent=2),encoding="utf-8");tmp.replace(out/"results.json")

def diagnose(out):
    out.mkdir(parents=True,exist_ok=True)
    p,_,_,_,_=build_payload(out,"left",0)
    result=transport(p)
    (out/"diagnostic.json").write_text(json.dumps(result,indent=2),encoding="utf-8")
    print(json.dumps(result),flush=True)

def main(out,live=False):
    if live and (os.getenv("GITHUB_ACTIONS")!="true" or not os.getenv("TYPESAFE_API_KEY")):raise SystemExit("Actions and repository secret required; no live call")
    out.mkdir(parents=True,exist_ok=True)
    report={"experiment":"Native Score bridge and Generic Space fan-out v5","status":"running" if live else "offline_only","model":"jev-1.14.0","source_commit":os.getenv("GITHUB_SHA"),"run_id":os.getenv("GITHUB_RUN_ID"),"profiles":PROFILES,"limits":LIMITS,"memory_provenance":{"file":MEMORY_PATH.relative_to(ROOT).as_posix(),"sha256":hashlib.sha256(MEMORY_PATH.read_bytes()).hexdigest(),"entries":MEMORY["entries"]},"scaling_scenarios":[{"generic_schemas":n,"coarse_one_score_each_questions":n,"five_bridges_three_axes_questions":5*3*n,"illustrative_80_tokens_per_coarse_question":80*n,"measurement_status":"sizing_only_not_live"} for n in (200,2000)],"calls":[]}
    for shape in geometry.SHAPES:
        for repeat in range(2):
            payload,mapping,meta,audit,probe=build_payload(out,shape,repeat)
            order=("probe","full") if repeat%2==0 else ("full","probe")
            for kind in order:
                p=copy.deepcopy(payload)
                if kind=="probe":p["questions"]={k:v for k,v in p["questions"].items() if k in probe}
                record={"shape":shape,"repeat":repeat,"kind":kind,"question_count":len(p["questions"]),"body_bytes":len(json.dumps(p).encode()),"candidate_mapping":mapping,"question_metadata":{k:meta[k] for k in p["questions"]},"asset_audit":audit,"model_input":{k:v for k,v in p.items() if k!="assets"},"request_sha256":hashlib.sha256(json.dumps(p,sort_keys=True).encode()).hexdigest()}
                if live:record.update(transport(p))
                report["calls"].append(record);save(out,report);print("Recorded",len(report["calls"]),"/ 8",kind,len(p["questions"]),flush=True)
    report["status"]="completed_with_failures" if live and any("failure" in r for r in report["calls"]) else "completed" if live else "offline_only"
    save(out,report);viewer(out,report)
    if report["status"]=="completed_with_failures":raise SystemExit("Sanitized failures recorded")

if __name__=="__main__":
    ap=argparse.ArgumentParser();ap.add_argument("--out",type=Path,default=Path("output_native_scores"));ap.add_argument("--live",action="store_true");ap.add_argument("--diagnose",action="store_true");a=ap.parse_args();diagnose(a.out) if a.diagnose else main(a.out,a.live)
